type Outcome =
  | "complete"
  | "truncated"
  | "refused"
  | "tool_request"
  | "paused"
  | "other";

interface ModelResult {
  provider: "anthropic" | "openai" | "google";
  surface: "messages" | "responses" | "generateContent" | "interactions";
  model: string;
  outcome: Outcome;
  text: string;
  toolCalls: { id: string; name: string; args: unknown }[];
  rawStop: string | null;
  rawUsage: Record<string, unknown>;
}

function claudeOutcome(stop: string | null): Outcome {
  switch (stop) {
    case "end_turn": return "complete";
    case "max_tokens": return "truncated";
    case "refusal": return "refused";
    case "tool_use": return "tool_request";
    case "pause_turn": return "paused";
    default: return "other";
  }
}

function geminiGenerateContentOutcome(finishReason: string | undefined): Outcome {
  return finishReason === "STOP" ? "complete" : "other";
}

function geminiInteractionOutcome(status: string | undefined): Outcome {
  if (status === "completed") return "complete";
  if (status === "requires_action") return "tool_request";
  return "other";
}

// Every guarantee the application depends on, and the request field it rides on.
const guarantees = [
  { name: "tool arguments match the schema", field: "tools[].function.strict" },
  { name: "final answer matches a JSON schema", field: "response_format" },
  { name: "a refusal is machine-detectable", field: "choices[].message.refusal" },
];

// Documented behavior of Claude behind Anthropic's OpenAI SDK compatibility layer:
//   tools[].function.strict     -> ignored
//   response_format             -> ignored
//   choices[].message.refusal   -> always empty
// These guarantees fail on that route. Do not assign the same behavior to
// Google's compatibility route unless Google's documentation establishes it.

interface Route {
  provider: "anthropic" | "openai" | "google";
  surface: "messages" | "responses" | "generateContent" | "interactions";
  model: string;
  store: boolean;
  verifiedOn: string;
  verifiedAt: string;
}

export function assertRoute(route: Route): Route {
  if (!route.model) throw new Error("A reviewed model identifier is required");
  if (!route.verifiedOn || !route.verifiedAt) {
    throw new Error("Route verification provenance is required");
  }
  if (route.surface === "messages" && route.store) {
    throw new Error("This store setting is not available on Claude Messages");
  }
  return route;
}

export async function withRetry(operation, policy) {
  const started = Date.now();
  let lastError;

  for (let attempt = 1; attempt <= policy.maxAttempts; attempt += 1) {
    policy.signal?.throwIfAborted();
    if (Date.now() - started >= policy.budgetMs) break;

    try {
      return await operation({ attempt, signal: policy.signal });
    } catch (error) {
      lastError = error;
      if (policy.classifyError(error) !== "transient") throw error;
      if (attempt === policy.maxAttempts) throw error;
    }
  }

  throw lastError ?? new Error("Retry budget exhausted");
}

